const { execFile } = require('child_process');

// Renders a user-supplied hostname unreachable to a shell: execFile does not spawn one,
// and every argument is a separate argv entry.
function pingHost(host, cb) {
  if (!/^[a-zA-Z0-9.-]{1,253}$/.test(host)) return cb(new Error('invalid host'));
  execFile('/sbin/ping', ['-c', '3', host], { timeout: 5000 }, (err, stdout) => {
    if (err) return cb(err);
    cb(null, stdout);
  });
}

module.exports = { pingHost };
